require __DIR__ . '/../app/bootstrap.php'; require_admin(); require_once __DIR__ . '/../app/recurring_charges.php'; $user=current_user(); if($_SERVER['REQUEST_METHOD']!=='POST')sync_recurring_charges($pdo);
$dir=__DIR__.'/../backups';if(!is_dir($dir))mkdir($dir,0750,true);
function dbcli(): ?string {
 $candidates=array_merge(glob('C:/wamp64/bin/mysql/mysql*/bin/mysql.exe')?:[],glob('C:/wamp64/bin/mariadb/mariadb*/bin/mariadb.exe')?:[],glob('C:/wamp64/bin/mariadb/mariadb*/bin/mysql.exe')?:[]);
 foreach($candidates as $f)if(is_file($f))return $f;
 $which=trim((string)@shell_exec('where mysql.exe 2>NUL'));if($which!=='')return trim(explode("\n",$which)[0]);
 return null;
}
function run_sql_cli(string $file): void {
 $cfg=require __DIR__.'/../config/config.php';$bin=dbcli();if(!$bin)throw new RuntimeException('No se encuentra mysql.exe/mariadb.exe. Comprueba la instalación de WAMP.');
 $cmd=[$bin,'--host='.$cfg['db_host'],'--user='.$cfg['db_user'],'--default-character-set=utf8mb4'];
 if($cfg['db_pass']!=='')$cmd[]='--password='.$cfg['db_pass'];
 $cmd[]=$cfg['db_name'];
 $pipes=[];$proc=proc_open($cmd,[['pipe','r'],['pipe','w'],['pipe','w']],$pipes);
 if(!is_resource($proc))throw new RuntimeException('No se pudo iniciar el cliente de base de datos.');
 $fh=fopen($file,'rb');if(!$fh){fclose($pipes[0]);throw new RuntimeException('No se puede leer el archivo SQL.');}
 while(!feof($fh)){ $chunk=fread($fh,8192);if($chunk===false)break;fwrite($pipes[0],$chunk); }
 fclose($fh);fclose($pipes[0]);$out=stream_get_contents($pipes[1]);fclose($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[2]);$code=proc_close($proc);
 if($code!==0)throw new RuntimeException('El cliente SQL devolvió un error. Revisa el archivo SQL y los datos de conexión. '.$err);
}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='create'){
   $cfg=require __DIR__.'/../config/config.php';$bin=dbcli();if(!$bin)throw new RuntimeException('No se encuentra mysql.exe/mariadb.exe en WAMP.');
   $dump=null;foreach(array_merge(glob('C:/wamp64/bin/mysql/mysql*/bin/mysqldump.exe')?:[],glob('C:/wamp64/bin/mariadb/mariadb*/bin/mariadb-dump.exe')?:[],glob('C:/wamp64/bin/mariadb/mariadb*/bin/mysqldump.exe')?:[]) as $f){if(is_file($f)){$dump=$f;break;}}
   if(!$dump)throw new RuntimeException('No se encuentra mysqldump.exe/mariadb-dump.exe en WAMP.');
   $name='backup_'.date('Y-m-d_H-i-s').'.sql';$path=$dir.'/'.$name;$cmd=[$dump,'--host='.$cfg['db_host'],'--user='.$cfg['db_user'],'--default-character-set=utf8mb4'];if($cfg['db_pass']!=='')$cmd[]='--password='.$cfg['db_pass'];$cmd[]=$cfg['db_name'];
   $pipes=[];$proc=proc_open($cmd,[['pipe','r'],['file',$path,'w'],['pipe','w']],$pipes);if(!is_resource($proc))throw new RuntimeException('No se pudo iniciar mysqldump.');fclose($pipes[0]);$errDump=stream_get_contents($pipes[2]);fclose($pipes[2]);$code=proc_close($proc);
   if($code!==0||!is_file($path)||filesize($path)<50){@unlink($path);throw new RuntimeException('No se pudo crear la copia SQL. '.$errDump);}$msg='Copia creada: '.$name;
  }elseif($action==='delete'){
   $name=basename($_POST['name']??'');if(!preg_match('/^(backup|uploaded)_[0-9-]+_[0-9-]+\.sql$/',$name)||!is_file($dir.'/'.$name))throw new RuntimeException('Copia no válida.');unlink($dir.'/'.$name);$msg='Copia eliminada.';
  }elseif($action==='restore'){
   $name=basename($_POST['name']??'');if(!preg_match('/^(backup|uploaded)_[0-9-]+_[0-9-]+\.sql$/',$name)||!is_file($dir.'/'.$name))throw new RuntimeException('Selecciona una copia válida.');
   if(($_POST['confirmacion']??'')!=='RESTAURAR')throw new RuntimeException('Escribe RESTAURAR para confirmar. Antes de continuar, descarga una copia del estado actual.');
   run_sql_cli($dir.'/'.$name);$msg='Restauración terminada. Cierra sesión y vuelve a entrar si fuese necesario.';
  }elseif($action==='upload_restore'){
   if(empty($_FILES['sqlfile']['tmp_name'])||($_FILES['sqlfile']['error']??1)!==UPLOAD_ERR_OK)throw new RuntimeException('Selecciona un archivo SQL válido.');
   if((int)$_FILES['sqlfile']['size']>20*1024*1024)throw new RuntimeException('El archivo supera el límite de 20 MB.');
   $tmp=file_get_contents($_FILES['sqlfile']['tmp_name']);if($tmp===false||stripos($tmp,'<html')!==false||strpos($tmp,';')===false)throw new RuntimeException('El archivo no parece un volcado SQL válido.');
   $name='uploaded_'.date('Y-m-d_H-i-s').'.sql';$path=$dir.'/'.$name;if(!move_uploaded_file($_FILES['sqlfile']['tmp_name'],$path))throw new RuntimeException('No se pudo guardar el archivo SQL.');
   if(($_POST['confirmacion']??'')!=='RESTAURAR'){$msg='Archivo guardado como '.$name.'. Para restaurarlo, escribe RESTAURAR en su fila y pulsa Restaurar.';}else{run_sql_cli($path);$msg='Archivo SQL restaurado correctamente.';}
  }
 }catch(Throwable $e){$err=$e->getMessage();}
}
$files=glob($dir.'/*.sql')?:[];usort($files,fn($a,$b)=>filemtime($b)<=>filemtime($a));
