true">💾</span><span>Copias de seguridad</span></a><?php endif;?><div class="nav-spacer"></div><?php if($user['rol']==='ADMIN'):?><a class="nav-item" href="configuracion.php"><span class="nav-icon" aria-hidden="true">🛠️</span><span>Configuración</span></a><?php endif;?><a class="nav-item nav-help" href="ayuda.php"><span class="nav-icon" aria-hidden="true">❔</span><span>Ayuda y manual</span></a></div></nav><main class="content"><h1>Copias de seguridad</h1><p class="muted">Incluye ubicaciones, unidades, inquilinos, cargos, ingresos, fianzas y usuarios. Solo accesible para administradores.</p><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice error"><?=e($err)?></div><?php endif;?><section class="panel"><h3>Crear copia en el servidor</h3><p>Genera un volcado SQL en la carpeta privada backups del proyecto.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><button class="btn primary">Crear copia ahora</button></form></section><section class="panel"><h3>Subir SQL y restaurar</h3><p>Restaurar puede sobrescribir datos. Haz primero una copia de seguridad actual.</p><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="upload_restore"><div class="full"><label>Archivo .sql (máximo 20 MB)</label><input type="file" name="sqlfile" accept=".sql" required></div><div><label>Confirmación (escribe RESTAURAR)</label><input name="confirmacion" placeholder="RESTAURAR"></div><div class="full"><button class="btn outline" onclick="return confirm('La restauración puede sobrescribir datos. ¿Continuar?')">Subir y restaurar SQL</button></div></form></section><section class="panel"><h3>Copias guardadas</h3><div class="table-wrap"><table><tr><th>Archivo</th><th>Fecha</th><th>Tamaño</th><th>Acciones</th></tr><?php foreach($files as $f):?><tr><td><?=e(basename($f))?></td><td><?=date('d/m/Y H:i',filemtime($f))?></td><td><?=number_format(filesize($f)/1024,1,',','.')?> KB</td><td><div class="actions"><a class="btn outline" href="download_backup.php?name=<?=rawurlencode(basename($f))?>">Descargar</a><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="name" value="<?=e(basename($f))?>"><input name="confirmacion" placeholder="Escribe RESTAURAR" required><button class="btn primary" onclick="return confirm('¿Restaurar esta copia? Los datos actuales pueden cambiar.')">Restaurar</button></form><form method="post" onsubmit="return confirm('¿Eliminar esta copia?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="name" value="<?=e(basename($f))?>"><button class="btn danger">Borrar</button></form></div></td></tr><?php endforeach;?><?php if(!$files):?><tr><td colspan="4" class="empty">Todavía no hay copias guardadas.</td></tr><?php endif;?></table></div><p class="muted">Si la copia contiene instrucciones para otra base de datos, comprueba el archivo antes de restaurar.</p><a class="btn outline" href="http://localhost/phpmyadmin/" target="_blank" rel="noopener">Abrir phpMyAdmin</a></section></main></div><script>document.addEventListener('DOMContentLoaded',()=>{const nav=document.querySelector('.sidebar');if(!nav)return;const btn=nav.querySelector('.mobile-menu-toggle');const links=nav.querySelector('.mobile-nav-links');if(!btn||!links)return;links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{if(window.matchMedia('(max-width:650px)').matches){nav.classList.remove('mobile-menu-open');btn.setAttribute('aria-expanded','false');btn.querySelector('.toggle-label').textContent='Menú principal';btn.querySelector('.toggle-icon').textContent='☰';}}));});</script></body></html>
